  if (missing.length) problems.push("missing=" + missing.join(","));
  if (unknown.length) problems.push("unknown=" + unknown.join(","));
  if (nonFunctions.length) problems.push("not_functions=" + nonFunctions.join(","));
  if (problems.length) {
    throw new TypeError("action_parity_handler_mismatch: " + problems.join(" "));
  }
